def investigate(context, acquire):
    history = acquire("history")
    goal = context.get("goal")
    actions = context.get("actions", [])

    def simulate(put_mode, trigger, channel_mode):
        # put_mode: 'ignore', 'replace', 'upsert'
        # trigger: False or True (AFTER INSERT trigger logging one row)
        # channel_mode: 'changes', 'total_main', 'total_both'
        items = {}
        log_count = 0
        main_total = 0
        other_total = 0
        main_changes = 0
        in_tx = False
        tx_conn = None
        tx_snapshot = None
        tx_log_snapshot = None
        tx_main_total_snapshot = None
        tx_other_total_snapshot = None
        tx_changes_snapshot = None

        def do_put(conn, key, value):
            nonlocal log_count, main_total, other_total, main_changes
            changed = 0
            inserted = False
            if key in items:
                if put_mode == 'ignore':
                    changed = 0
                elif put_mode == 'replace':
                    items[key] = value
                    changed = 1
                else:  # upsert
                    items[key] = value
                    changed = 1
            else:
                items[key] = value
                changed = 1
                inserted = True
            if inserted and trigger:
                log_count += 1
            if conn == 'main':
                main_total += changed
                main_changes = changed
            else:
                other_total += changed

        def do_update(conn, key, value):
            nonlocal log_count, main_total, other_total, main_changes
            changed = 0
            if key in items:
                items[key] = value
                changed = 1
            if conn == 'main':
                main_total += changed
                main_changes = changed
            else:
                other_total += changed

        def do_delete(conn, key):
            nonlocal log_count, main_total, other_total, main_changes
            changed = 0
            if key in items:
                del items[key]
                changed = 1
            if conn == 'main':
                main_total += changed
                main_changes = changed
            else:
                other_total += changed

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'put':
                do_put(conn, act.get('key'), act.get('value'))
            elif op == 'update':
                do_update(conn, act.get('key'), act.get('value'))
            elif op == 'delete':
                do_delete(conn, act.get('key'))
            elif op == 'begin':
                in_tx = True
                tx_conn = conn
                tx_snapshot = dict(items)
                tx_log_snapshot = log_count
                tx_main_total_snapshot = main_total
                tx_other_total_snapshot = other_total
                tx_changes_snapshot = main_changes
            elif op == 'commit':
                in_tx = False
                tx_conn = None
            elif op == 'rollback':
                if tx_snapshot is not None:
                    items.clear()
                    items.update(tx_snapshot)
                    log_count = tx_log_snapshot
                    main_total = tx_main_total_snapshot
                    other_total = tx_other_total_snapshot
                    main_changes = tx_changes_snapshot
                in_tx = False
                tx_conn = None

        if channel_mode == 'changes':
            ch = main_changes
        elif channel_mode == 'total_main':
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(items), sum(items.values())

    modes = ['ignore', 'replace', 'upsert']
    triggers = [False, True]
    channels = ['changes', 'total_main', 'total_both']

    candidates = []
    for pm in modes:
        for tr in triggers:
            for cm in channels:
                candidates.append((pm, tr, cm))

    def matches(rec):
        obs = rec.get('observed', {})
        acts = rec.get('actions', [])
        for pm in modes:
            for tr in triggers:
                for cm in channels:
                    ch, cnt, sm = simulate(pm, tr, cm)
                    if ch == obs.get('channel') and cnt == obs.get('committed_count') and sm == obs.get('committed_sum'):
                        pass
        return True

    # Filter candidates by all history receipts
    valid = []
    for pm, tr, cm in candidates:
        ok = True
        for rec in history:
            obs = rec.get('observed', {})
            acts = rec.get('actions', [])
            ch, cnt, sm = simulate(pm, tr, cm)
            if ch != obs.get('channel') or cnt != obs.get('committed_count') or sm != obs.get('committed_sum'):
                ok = False
                break
        if ok:
            valid.append((pm, tr, cm))

    if not valid:
        return {"value": None, "unresolved": True}

    results = set()
    for pm, tr, cm in valid:
        ch, cnt, sm = simulate(pm, tr, cm)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cnt)
        elif goal == 'committed_sum':
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}

